import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Row, Col, Button, Icon } from 'antd'
import moment from 'moment-timezone'
import actionsGroups from '../../../redux/customer-support/actions'
import { BASE_IMG_URL_S3 } from '../../../../helpers/constant'

const { previewSelected } = actionsGroups
let messageDifference = ''

class MessageBodyPart extends Component {
  constructor (props) {
    super(props)
    this.state = {
      messageDifference: '',
      displayTime: ''
    }
    this.messagesEnd = React.createRef()
  }

  componentDidMount () {
    this.scrollToBottom()
  }

  componentDidUpdate () {
    this.scrollToBottom()
  }

  imagePreviewFunction (image) {
    var data = {
      showModal: true,
      image: image
    }
    this.props.previewSelected(data)
  }

  scrollToBottom = () => {
    this.messagesEnd.current.scrollIntoView({ behavior: 'auto' })
  }

  getTime = (time) => {
    const { profileData } = this.props
    let messageTimeStamp = moment.utc(time).tz(profileData && profileData.user_timezone)
    let currentTimeStamp = moment.utc().tz(profileData && profileData.user_timezone)
    let difference = currentTimeStamp.diff(messageTimeStamp, 'days')

    switch (difference) {
      case 0:
        if (messageDifference !== messageTimeStamp.format('DD/MM/YYYY')) {
          messageDifference = messageTimeStamp.format('DD/MM/YYYY')
          return 'Today'
        } else return ''
      case 1:
        if (messageDifference !== messageTimeStamp.format('DD/MM/YYYY')) {
          messageDifference = messageTimeStamp.format('DD/MM/YYYY')
          return 'Yesterday'
        } else return ''
      default:
        if (messageDifference !== messageTimeStamp.format('DD/MM/YYYY')) {
          messageDifference = messageTimeStamp.format('DD/MM/YYYY')
          return messageTimeStamp.format('DD/MM/YYYY')
        } else return ''
    }
  }

  render () {
    const {
      messages,
      contanctData
    } = this.props

    return (
      <React.Fragment>
        <Col>
          <Row className='message-body-container'>
            {
              messages && messages.map((item = {}) => {
                const time = this.getTime(item.timestamp)
                return <div>
                  <Row align='middle' justify='center'>
                    {
                      time !== '' &&
                      <div className='message-chat-time'>
                        {time}
                      </div>
                    }
                  </Row>
                  {item.message_type === 'received'
                    ? <Row className='Messages-list right'>
                      <Row type='flex' align='middle' className='w100'>
                        <Col className='name-logo'>
                          <span>
                            <img
                              src={(contanctData && contanctData.profile_picture) || `${BASE_IMG_URL_S3}/gosure/user_default_icon%202.png`}
                              className='profile-picture'
                              alt=''
                            />
                          </span>
                        </Col>
                        <Col className='arrow-box left-arrow'>
                          {
                            ((item && item.content_type) === 'text')
                              ? <p>
                                {item.content.body}
                              </p>
                              : <p>
                                {
                                  (item && item.content_type === 'image')
                                    ? <React.Fragment>
                                      <div className='message-image'>
                                        <img
                                          src={item.content && item.content.url}
                                          onClick={() => { this.imagePreviewFunction(item.content ? item.content.url : '') }}
                                          alt=''
                                        />
                                      </div>
                                      <p>
                                        {item.content && item.content.caption}
                                      </p>
                                    </React.Fragment>
                                    : <React.Fragment>
                                      <p>
                                        <b>
                                          {item.content && item.content.caption}
                                        </b>
                                      </p>
                                      <div className='padding10 w100'>
                                        <Button
                                          href={item.content && item.content.url}
                                          className='download-button'
                                          target='_blank'
                                          download>
                                          {'Download'}
                                        </Button>
                                      </div>
                                    </React.Fragment>
                                }
                              </p>
                          }
                          <Row type='flex' justify='space-between'>
                            {
                              item.status === 'failed' && <Icon type='exclamation-circle' style={{ color: 'red' }} />
                            }
                            {
                              item.timestamp && moment(item.timestamp).format('HH:mm')
                            }
                          </Row>
                        </Col>
                      </Row>
                    </Row>
                    : <Row span={24} className='Messages-list left'>
                      <Row type='flex' className='w100' gutter={10}>
                        <Col className='arrow-box right-arrow'>
                          {
                            (item.content && item.content.body)
                              ? <p>{item.content.body}</p>
                              : <p>
                                {
                                  (item && item.content_type === 'image')
                                    ? <React.Fragment>
                                      <div className='message-image'>
                                        <img
                                          src={item.content && item.content.url}
                                          onClick={() => { this.imagePreviewFunction(item.content ? item.content.url : '') }}
                                          alt=''
                                        />
                                      </div>
                                      <p>{item.content && item.content.caption}</p>
                                    </React.Fragment>
                                    : <React.Fragment>
                                      <p>
                                        <b>
                                          {item.content && item.content.caption}
                                        </b>
                                      </p>
                                      <div className='padding10 w100'>
                                        <Button
                                          href={item.content && item.content.url}
                                          className='download-button'
                                          target='_blank'
                                          download>
                                          {'Download'}
                                        </Button>
                                      </div>
                                    </React.Fragment>
                                }
                              </p>
                          }
                          <Row type='flex' justify='space-between'>
                            {
                              item.timestamp && moment(item.timestamp).format('HH:mm')
                            }
                            {
                              item.status === 'failed' && <Icon type='exclamation-circle' style={{ color: 'red' }} />
                            }
                          </Row>
                        </Col>
                        <Col className='name-logo'>
                          <p className='pasar-polis-icon'>P</p>
                        </Col>
                      </Row>
                    </Row>
                  }
                </div>
              }
              )
            }
          </Row>
          <div
            ref={this.messagesEnd} />
        </Col>
      </React.Fragment>
    )
  }
}

export default connect(state =>
  ({
    contanctData: state.CustomerSupport.contanctData,
    profileData: state.Auth.profile
  }),
{
  previewSelected
})(MessageBodyPart)
