import React, { Component } from 'react'
import { connect } from 'react-redux'
import Cookies from 'universal-cookie'
import {
  TopHeader,
  MainBodyPart,
  ChatInputWrapper
} from '../IncomingMessage.style'
import { Col, Row, Spin, Avatar } from 'antd'
import MessageBodyPart from './MessageBodyPart'
import ChatInput from './ChatInput'
import actionsGroup from '../../../redux/customer-support/actions'

const { readWhatsappStatus, getWhatsappData, getWhatsappList, resetRedux } = actionsGroup
const cookies = new Cookies()

class RightPart extends Component {
  constructor (props) {
    super(props)
    this.state = {
      data: [],
      name: '',
      image: '',
      intervalId: '',
      readStatus: '',
      textHeight: 280
    }
  }

  componentDidMount () {
    const { getWhatsappData } = this.props
    var interval = setInterval(() => {
      getWhatsappData(cookies.get('whatsapp-no'))
    }, 30000)

    this.setState({
      intervalId: interval
    })
  }

  componentWillReceiveProps (nextProps) {
    const { individualDetailData, individualMessage, contanctData } = nextProps

    if (individualMessage === 'success') {
      this.setState({
        data: [...individualDetailData],
        name: (contanctData && contanctData.first_number) || cookies.get('whatsapp-no'),
        image: (contanctData && contanctData.image_number) || cookies.get('images')
      }, () => {
        const { data } = this.state
        let dataArray = data[0] ? data[0].messages : ' '
        let filteredData = []
        dataArray.forEach(item => {
          if (item.status === 'unread') {
            filteredData.push(item.id)
          }
        })
        let payloadData = {
          recipient_id: data[0].recipient,
          message_ids: filteredData
        }
        this.props.readWhatsappStatus(payloadData)
        this.props.resetRedux()
      })
    }
  }

  // reloadData =()=>{
  //     this.props.getWhatsappList()
  //     setTimeout(()=>{
  //         this.props.getWhatsappData(cookies.get('whatsapp-no'))
  //     },30000)
  //     this.setState({
  //         name: cookies.get('whatsapp-no'),
  //         image: cookies.get('images')
  //     })
  // }

  componentWillUnmount () {
    clearInterval(this.state.intervalId)
  }

  render () {
    const { mainbodyLoading } = this.props
    const {
      data,
      name,
      image,
      textHeight
    } = this.state

    return (
      <div id='message-body-container'>
        <TopHeader>
          <Row>
            <Col className='flex-container'>
              <Row type='flex' align='middle'>
                <Col className='padding10'>
                  <img src={image || <Avatar size='large' icon='user' />} className='profile-picture' alt='Profile' />
                </Col>
                <Col align='middle'>
                  <p>
                    <b>
                      {name || ' '}
                    </b>
                  </p>
                </Col>
              </Row>
            </Col>
          </Row>
        </TopHeader>

        {/* MainBodyPart Wrapper from styled component  start Here */}
        <Row className='overflowAuto message-container-height'>
          <Col xs={24}>
            <Spin spinning={mainbodyLoading}>
              <MainBodyPart textHeight={textHeight}>
                <MessageBodyPart messages={data[0] ? data[0].messages : ''} />
              </MainBodyPart>
            </Spin>
          </Col>
        </Row>
        {/* MainBodyPart Wrapper from styled component  end Here */}

        {/* ChatInput Wrapper from styled component  starts Here */}
        <ChatInputWrapper className='chatInputBox'>
          <ChatInput inputBoxHeight={(textHeight) => this.setState({ textHeight: 230 + textHeight })} />
        </ChatInputWrapper>
        {/* ChatInput Wrapper from styled component  end Here */}

      </div>
    )
  }
}

export default connect(
  state => ({
    individualDetailData: state.CustomerSupport.individualDetailMessage,
    individualMessage: state.CustomerSupport.individualMessage,
    contanctData: state.CustomerSupport.contanctData,
    mainbodyLoading: state.Loading.WHATSAPP_DETAIL_MESSAGE,
    listmessage: state.CustomerSupport.listDataMessageDisplay
  }),
  {
    getWhatsappList,
    getWhatsappData,
    readWhatsappStatus,
    resetRedux
  }
)(RightPart)
