import React, { Component } from 'react'
import { connect } from 'react-redux'

import {
  ChatContainer,
  LeftRowContainerWrapper,
  RightRowContainerWrapper
} from './IncomingMessage.style'
import LeftPart from './MessageComponents/LeftPart'
import { Row, Col, Modal } from 'antd'
import Cookies from 'universal-cookie'

import RightPart from './MessageComponents/RightPart'
import actionsGroupsCall from '../../redux/customer-support/actions'

const cookies = new Cookies()
const { getWhatsappList, imageBlank } = actionsGroupsCall
class IncomingMessage extends Component {
  constructor (props) {
    super(props)
    this.state = {
      previewVisible: false,
      image: ''
    }
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.imageSelectedUrl !== undefined) {
      const { imageSelectedUrl } = nextProps

      this.setState({
        previewVisible: imageSelectedUrl.showModal,
        image: imageSelectedUrl.image
      })
    }
  }
  componentDidMount () {
    this.props.getWhatsappList({
      page: 1 // initial page
    })
  }

  handleCancelShowImg = () => this.setState({ previewVisible: false }, () => { this.props.imageBlank() });
  componentWillUnmount () {
    cookies.remove('whatsapp-no')
    cookies.remove('images')
  }
  render () {
    const { selectedCardFromLeft } = this.props
    // let footHeight = document.getElementById('footer').clientHeight
    return (
      <Row>
        <ChatContainer>
          <Modal
            visible={this.state.previewVisible}
            onCancel={this.handleCancelShowImg}
            footer={null}
          >
            <img src={
              this.state.image
            } style={{ width: '100%', height: 'auto' }} alt='' />

          </Modal>
          <Row>
            <Col xs={6}>
              <LeftRowContainerWrapper>
                <LeftPart />
              </LeftRowContainerWrapper>
            </Col>
            {
              (selectedCardFromLeft !== '')
                ? <Col xs={18}>
                  <RightRowContainerWrapper>
                    <RightPart />
                  </RightRowContainerWrapper>
                </Col>
                : ''
            }
          </Row>
        </ChatContainer>
      </Row>
    )
  }
}

IncomingMessage.propTypes = {

}

export default connect(
  state => ({
    individualMessage: state.CustomerSupport.individualMessage,
    selectedCardFromLeft: state.CustomerSupport.contanctData,
    imageSelectedUrl: state.CustomerSupport.imageSelected
  }),
  {
    getWhatsappList,
    imageBlank
  }
)(IncomingMessage)
