import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Row, Col } from 'antd'
import moment from 'moment-timezone'
import loadingWhatasppAction from '../../../redux/customer-support/actions'
import { BASE_IMG_URL_S3 } from '../../../../helpers/constant'

const { showFirstRenderData, displayContactData } = loadingWhatasppAction

class ContactsCards extends Component {
  constructor (props) {
    super(props)
    this.state = {
      hideCard: [],
      val: '',
      firstCard: false
    }
  }

  getTime = () => {
    const { data, profileData } = this.props
    const { last_message_timestamp: lastMessageTimestamp } = data
    let messageTimeStamp = moment.utc(lastMessageTimestamp).tz(profileData && profileData.user_timezone)
    let currentTimeStamp = moment.utc().tz(profileData && profileData.user_timezone)
    let difference = currentTimeStamp.diff(messageTimeStamp, 'days')

    switch (difference) {
      case 0:
        return messageTimeStamp.format('HH:MM')
      case 1:
        return 'Yesterday'
      default:
        return messageTimeStamp.format('DD/MM/YYYY')
    }
  }

  parentCall = (number, id, image) => {
    var data = []
    data.push(id)
    this.setState({
      hideCard: data,
      val: id
    }, () => {
      let obj = {
        first_number: number,
        image_number: image
      }
      this.props.displayContactData(obj)
      this.props.openingCard(number, id, image)
    })
  }

  render () {
    const {
      data = {},
      showactivecard
    } = this.props
    const { val } = this.state
    const {
      id,
      number,
      unread_count: unreadCount,
      profile_picture: profilePicture,
      last_message_snippet: lastMessageSnippet
    } = data

    let activeCardStyle = 'activeCardStyle'
    let nonActiveCardStyle = 'nonActiveCardStyle'

    return (
      <div
        className={showactivecard === id ? activeCardStyle : nonActiveCardStyle}
        onClick={() => this.parentCall((number), (id), (profilePicture || `${BASE_IMG_URL_S3}/gosure/user_default_icon%202.png`))}>
        <Row type='flex' align='middle' justify='space-around' className='padding10'>
          <Col span={4}>
            <img src={profilePicture || `${BASE_IMG_URL_S3}/gosure/user_default_icon%202.png`} className='profile-picture' alt='' />
          </Col>
          <Col span={18}>
            <Row type='flex' className='justify-space-between'>
              <Col className='color-white'>
                <b>
                  {number || ''}
                </b>
              </Col>
              <Col className='small-text color-white'>
                {this.getTime()}
              </Col>
            </Row>
            <Row type='flex' className='justify-space-between'>
              <Col span={18} className='color-white'>
                <p className='message-review'>
                  <small>
                    {lastMessageSnippet}
                  </small>
                </p>
              </Col>
              {
                (unreadCount > 0) && (val !== id) &&
                <Col span={3} className='small-text'>
                  <p className='badge'>
                    {unreadCount}
                  </p>
                </Col>
              }
            </Row>
          </Col>
        </Row>
      </div>
    )
  }
}

export default connect(
  state => ({
    profileData: state.Auth.profile
  }),
  {
    displayContactData,
    showFirstRenderData
  }
)(ContactsCards)
