import React, { Component } from 'react'
import { connect } from 'react-redux'
import Cookies from 'universal-cookie'
import ContactsCards from './ContactsCards'
import { Row, Col, Divider, Input } from 'antd'
import loadingWhatasppActions from '../../../redux/customer-support/actions'
import { debounce } from '../../../../helpers/utility'

const { getWhatsappData, getWhatsappList } = loadingWhatasppActions
const cookies = new Cookies()

class LeftPart extends Component {
  constructor (props) {
    super(props)
    this.state = {
      contactList: [],
      showCardActiveId: '',
      number: '',
      read: '',
      firstData: [],
      firstRenderNumber: '',
      searchdata: [],
      value: '',
      query: ''
    }
    this.intervalLeft = null
    this.page = 1
    this.isScrolling = false
    this.isSearch = false
    this.lastScrollTop = 0
  }

  componentWillReceiveProps (nextProps) {
    const { listDatamessage, listData, isIntervalUpdate, chatMetaData } = nextProps
    if (listDatamessage === 'success') {
      let restList = []
      const { searchData } = this.state
      if (isIntervalUpdate) {
        // update only the top result per page so that
        // user only gets the top page result updated
        // if any chat gets updated then result will present in first view
        // remove duplicates check from the list
        restList = searchData.slice(chatMetaData.per_page, searchData.length)
        restList = [...listData, ...restList]
      } else {
        restList = searchData ? searchData.concat(listData) : listData
      }

      this.setState({
        searchData: this.isScrolling ? restList : listData,
        contactList: listData
      })
    }
  }

  componentDidMount = () => {
    this.startWatchWhatsAppPost()
  }

  componentWillUnmount () {
    clearInterval(this.intervalLeft)
    this.page = 1
  }

  startWatchWhatsAppPost = () => {
    const { getWhatsappList } = this.props
    this.intervalLeft = setInterval(
      function () {
        getWhatsappList({
          page: this.page, // initial page
          isIntervalUpdate: true
        })
      }, 30000
    )
  }

  renderDetaildata = (number, id, image) => {
    this.setState({
      showCardActiveId: id,
      read: id
    }, () => {
      if (number !== this.state.number) {
        cookies.set('whatsapp-no', number, { path: '/' })
        cookies.set('images', image, { path: '/' })
        this.props.getWhatsappData(number)
        this.setState({
          number
        })
      }
    })
  }

  onScrollContainer = (e) => {
    let element = e.target
    const { chatMetaData } = this.props
    const { query } = this.state
    const { pages } = chatMetaData
    if (element.scrollHeight - element.scrollTop === element.clientHeight) {
      // do something at end of scroll
      if (this.page + 1 > pages) {
        // if this.page greater the pages
        return
      }
      clearInterval(this.intervalLeft)
      this.isScrolling = true
      this.lastScrollTop = element.scrollTop
      this.page = this.page + 1
      this.props.getWhatsappList({
        page: this.page, // initial page
        query
      })
    } else if (this.page > 1 && this.isScrolling && (this.lastScrollTop > element.scrollTop)) {
      this.isScrolling = false
      this.startWatchWhatsAppPost()
    }
  }

  filterData = debounce(value => {
    this.isScrolling = false
    this.page = 1 // for search set the page 1
    if (this.intervalLeft) {
      clearInterval(this.intervalLeft)
    }

    let data = (value).toString()
    this.setState({ query: data })
    this.props.getWhatsappList({
      page: this.page, // initial page
      query: data
    })
  }, 200)

  render () {
    const {
      showCardActiveId,
      searchData
    } = this.state

    return (
      <div className='left-part-data left-section-scroll' onScroll={this.onScrollContainer}>
        <Row type='flex' justify='center' className='left-body'>
          <Col span={20}>
            <Input
              placeholder='Search...'
              onChange={e => this.filterData(e.target.value)}
            />
          </Col>
        </Row>
        <Divider className='divider' />
        <Row>
          <Col xs={24}>
            {/* <ContactsCards active/> */}
            {
              searchData && searchData.map((item, index) =>
                <ContactsCards
                  key={index}
                  data={item}
                  openingCard={this.renderDetaildata}
                  showactivecard={showCardActiveId}
                />
              )
            }
          </Col>
        </Row>
      </div>
    )
  }
}

export default connect(
  state => ({
    listData: state.CustomerSupport.listDataDetail,
    chatMetaData: state.CustomerSupport.chatMetaData,
    isIntervalUpdate: state.CustomerSupport.isIntervalUpdate,
    listDatamessage: state.CustomerSupport.listDataMessageDisplay
  }),
  {
    getWhatsappData,
    getWhatsappList
  }
)(LeftPart)
