import React, { Component } from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Upload,
  Form,
  message,
  Modal,
  Spin,
  Input
} from 'antd'
import { InputWrapper } from '../IncomingMessage.style'
import SendButton from '../../../../image/send-icn.png'
import UploadButton from '../../../../image/attach-icon.png'
import actionGroup from '../../../redux/customer-support/actions'

const { TextArea } = Input
const { sendWhatsappMessage, getWhatsappData, uploadData, getWhatsappList, resetRedux } = actionGroup
const dummyRequest = ({ onSuccess }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 0)
}

class ChatInput extends Component {
  constructor (props) {
    super(props)
    this.state = {
      message: '',
      idNo: '',
      loading: false,
      newurl: '',
      visible: false,
      imageMessage: '',
      fileType: ''
    }
  }

  componentWillReceiveProps (nextProps) {
    const { individualDetailData, individualMessage, uploadNewMessage, url } = nextProps
    if (individualMessage === 'success') {
      this.setState({
        idNo: [...individualDetailData][0].recipient
      })
    }
    if (uploadNewMessage === 'success') {
      this.setState({
        visible: true,
        imageMessage: ' ',
        newurl: url
      }, () => {
        this.props.resetRedux()
      })
    }
  }

  async handleChange (info) {
    if (info.file.status === 'done' || info.file.status === 'error') {
      // const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt20MB = info.file.size / 1024 / 1024 > 20
      // if (isLt10KB) {
      //   message.error('File is to small, min 10kb')
      //   return
      // }
      if (isGt20MB) {
        message.error('File is to big, max 20mb')
        return
      }
      if (!isGt20MB) { // eslint-disable-line
        const file = info.file.originFileObj
        this.setState({ filename: file.name, filesize: file.size, file, fileType: info.file.type })
        this.startUpload(file)
      } else {
        message.error('File is not supported')
      }
    }
  }

  startUpload = (file) => {
    this.setState({ loading: true })
    let formData = new FormData()
    formData.append('file', file)
    this.props.uploadData({ formData })
  }
  messageAccepting = (e) => {
    this.setState({ message: e.target.value })
  }
  imageMessage = (e) => {
    this.setState({ imageMessage: e.target.value })
  }
  sendingMessage = () => {
    const data = {
      WHATSAPP: {
        recipient_type: 'individual',
        to: this.state.idNo,
        type: 'text',
        body: this.state.message,
        whatsapp_type: 'chat'
      }
    }
    this.props.sendWhatsappMessage(data)
    this.setState({ message: '' })
    setTimeout(() => {
      this.props.getWhatsappList()
      this.props.getWhatsappData(this.state.idNo)
    }, 100)
  }

  handleOk = (url) => {
    const { fileType } = this.state
    let newImagedata = {}
    if ((fileType === 'image/jpeg') || (fileType === 'image/jpg') || (fileType === 'image/png')) {
      newImagedata = {
        WHATSAPP: {
          recipient_type: 'individual',
          to: this.state.idNo,
          type: 'image',
          image: {
            GCSURLs: [],
            PUBURLs: [
              {
                URL: url,
                Name: this.state.filename,
                Attach: true
              }
            ],
            caption: this.state.imageMessage
          },
          whatsapp_type: 'chat'
        }
      }
    } else {
      newImagedata = {
        WHATSAPP: {
          recipient_type: 'individual',
          to: this.state.idNo,
          type: 'document',
          document: {
            GCSURLs: [],
            PUBURLs: [
              {
                URL: url,
                Name: this.state.filename,
                Attach: true
              }
            ],
            caption: this.state.imageMessage
          },
          whatsapp_type: 'chat'
        }
      }
    }
    this.props.sendWhatsappMessage(newImagedata)
    this.setState({
      visible: false
    }, () => {
      setTimeout(() => {
        this.props.getWhatsappData(this.state.idNo)
        this.setState({ imageMessage: ' ' })
      }, 2000)
    })
  };

  enterPressed = () => {
    this.sendingMessage()
  }

  onClose = () => {
    this.props.resetRedux()
    this.setState({ visible: false, imageMessage: ' ' })
  };

  render () {
    const { url, uploadDataLoading } = this.props
    return (<React.Fragment>

      <Spin spinning={!!uploadDataLoading}>

        <Modal title='Preview' visible={this.state.visible} onOk={() => {
          this.handleOk(url)
        }} onCancel={this.onClose}>
          <Row type='flex' style={{
            flexDirection: 'column'
          }} gutter={40}>
            <Col span={24} style={{
              display: 'flex',
              justifyContent: 'center'
            }}>
              <img src={url} style={{
                maxWidth: 384,
                width: 'auto',
                height: 'auto',
                maxHeight: 400
              }} alt='' />
            </Col>
            <Col span={24} style={{
              display: 'flex',
              justifyContent: 'space-around',
              paddingTop: 10
            }}>
              <span>Message</span>
              <input type='text' onChange={(e) => {
                this.imageMessage(e)
              }} style={{
                width: '80%',
                border: '1px solid black',
                borderRadius: 8
              }} value={this.state.imageMessage} />
            </Col>
          </Row>
        </Modal>
      </Spin>

      <Col span={24} className='input_container chatSideButton'>
        <InputWrapper>
          <span id='first' className='chatSideButton'>
            <Upload name='file' showUploadList={false} multiple={false} customRequest={dummyRequest} onChange={file => this.handleChange(file)}>
              <img src={UploadButton} alt='upload' />
            </Upload>
          </span>
          <TextArea autosize={{ minRows: 1, maxRows: 6 }} className='customInput inputTypeBox' placeholder='Type Something ....'
            onChange={(e) => { this.messageAccepting(e) }} value={this.state.message} />

          <span id='second' className='chatSideButton' onClick={(e) => this.enterPressed(e)}>
            <img src={SendButton} alt='enter' />
          </span>
        </InputWrapper>
      </Col>
    </React.Fragment>)
  }
}
ChatInput.propTypes = {}

const WrappedForm = Form.create({})(ChatInput)
export default connect(
  state => ({
    individualDetailData: state.CustomerSupport.individualDetailMessage,
    individualMessage: state.CustomerSupport.individualMessage,
    recievSuccessMessage: state.CustomerSupport.sendSuccessMessage,
    url: state.CustomerSupport.uploadUrl,
    uploadNewMessage: state.CustomerSupport.uploadMessage,
    uploadDataLoading: state.Loading.UPLOAD_FILES
  }),
  {
    resetRedux,
    getWhatsappList,
    sendWhatsappMessage,
    getWhatsappData,
    uploadData
  }
)(WrappedForm)
